1	const PREFIX = "ivdr-draft";
2	
3	function storageKey(docId: string, sectionIdx: number): string {
4	  return `${PREFIX}-${docId}-${sectionIdx}`;
5	}
6	
7	export function getDraft(docId: string, sectionIdx: number): string | null {
8	  try {
9	    return localStorage.getItem(storageKey(docId, sectionIdx));
10	  } catch {
11	    return null;
12	  }
13	}
14	
15	export function setDraft(docId: string, sectionIdx: number, text: string): void {
16	  try {
17	    localStorage.setItem(storageKey(docId, sectionIdx), text);
18	  } catch {
19	    // storage full — ignore silently
20	  }
21	}
22	
23	export function clearDraft(docId: string, sectionIdx: number): void {
24	  try {
25	    localStorage.removeItem(storageKey(docId, sectionIdx));
26	  } catch {}
27	}
28	
29	export function hasDraft(docId: string, sectionIdx: number): boolean {
30	  return getDraft(docId, sectionIdx) !== null;
31	}
32	
33	export function clearAllDrafts(docId: string, sectionCount: number): void {
34	  for (let i = 0; i < sectionCount; i++) {
35	    clearDraft(docId, i);
36	  }
37	}
